\ELSE
  \STATE $b_{\mathrm{ESS}} \gets \textsc{Bisect}(\mathrm{ESS}(\cdot){=}n_{\min},\; [0, b_{\max}],\; \varepsilon)$
  \STATE \textbf{return} $b_{\mathrm{ESS}}$ \COMMENT{ESS-binding}
\ENDIF
\end{algorithmic}
\end{algorithm}

